import {match} from './model.mjs';
const $=id=>document.getElementById(id);
const exampleCV='Data Scientist · 2 года опыта\n\nРазрабатываю модели машинного обучения на Python. Использую Pandas, NumPy и Scikit-learn для подготовки данных и классификации.\n\nПроекты: прогноз оттока клиентов, анализ продаж, визуализация результатов в Matplotlib. Работаю с SQL и PostgreSQL. Версионирую код в Git. Изучаю NLP, есть учебный проект классификации отзывов.';
const exampleJob='Data Scientist · Middle\n\nИщем специалиста для разработки моделей машинного обучения на Python. Задачи: подготовка данных, классификация и анализ качества моделей.\n\nТребования: Python, SQL, Pandas, NumPy, Scikit-learn, Git. Опыт с NLP, PyTorch, Docker и FastAPI для вывода моделей в production. Навыки визуализации результатов.';
function counts(){for(const id of ['cv','job'])$(id+'-count').textContent=$(id).value.length+' симв.';}
function chips(id,items,missing=false){$(id).replaceChildren();if(!items.length){$(id).textContent=missing?'Все распознанные навыки упомянуты':'Нет совпадений';return;}items.forEach(item=>{const el=document.createElement('span');el.className='chip'+(missing?' missing':'');el.textContent=item;$(id).append(el);});}
function analyze(isExample=false){try{const r=match($('cv').value,$('job').value);$('error').textContent='';$('score').textContent=r.score;$('ring').style.background=`conic-gradient(#3265e8 ${r.score}%, #dbe6fb 0)`;$('verdict').textContent=r.score>=75?'Много общего':r.score>=45?'Есть точки совпадения':'Пока мало совпадений';$('summary').textContent=r.required.length?`${r.matched.length} из ${r.required.length} навыков вакансии найдены в резюме.`:'Навыки из словаря не распознаны. Оценка основана только на тексте.';$('coverage-value').textContent=r.coverage===null?'Н/Д':r.coverage+'%';$('lexical-value').textContent=r.lexical+'%';$('coverage-bar').style.width=(r.coverage??0)+'%';$('lexical-bar').style.width=r.lexical+'%';$('skill-weight').textContent=r.coverage===null?'0%':'65%';$('text-weight').textContent=r.coverage===null?'100%':'35%';$('skill-count').textContent=r.required.length+' В ВАКАНСИИ';chips('matched',r.matched);chips('missing',r.missing,true);if(!r.required.length)$('missing').textContent='Навыки из словаря не найдены';$('advice').textContent=r.missing.length?`Проверьте требования к ${r.missing.slice(0,3).join(', ')}. Если у вас есть такой опыт, добавьте в резюме конкретный проект и результат.`:'Добавьте примеры проектов и измеримые результаты, подтверждающие релевантный опыт.';$('result-state').textContent=isExample?'ДЕМО · ВЫЧИСЛЕНО':'АНАЛИЗ ГОТОВ';return r;}catch(e){$('error').textContent=e.message;$('result-state').textContent='ПРОВЕРЬТЕ ВВОД';return null;}}
function example(){ $('cv').value=exampleCV;$('job').value=exampleJob;counts();analyze(true);}
$('example').addEventListener('click',example);$('analyze').addEventListener('click',()=>analyze());['cv','job'].forEach(id=>$(id).addEventListener('input',()=>{counts();$('result-state').textContent='ПЕРЕСЧИТАЙТЕ РЕЗУЛЬТАТ';}));example();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'compare_documents',description:'Set resume and vacancy texts and calculate their match in the visible interface.',inputSchema:{type:'object',properties:{cv:{type:'string'},job:{type:'string'}},required:['cv','job'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){const result=match(input.cv,input.job);$('cv').value=input.cv;$('job').value=input.job;counts();analyze();return result;}})).catch(()=>{});}catch{}}
